#!/usr/bin/env python3
"""git-ops-recovery-factory mill r1460+: unique git-config/command plants, 16-step traces.

Not wrap-46. Not clones of r793–r1724 (advice-diverging-false, http-ssltry-false,
merge-conflictstyle-diff3, whoosh leftover3d, r1417 mill slugs). Distinct failure
class per episode.
"""
from __future__ import annotations

import argparse
import importlib.util
import json
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
_spec = importlib.util.spec_from_file_location("gor_mill_r1278", HERE / "gor-mill-r1278.py")
_r1278 = importlib.util.module_from_spec(_spec)
assert _spec.loader is not None
_spec.loader.exec_module(_r1278)

gitcfg = _r1278.gitcfg
cmdplant = _r1278.cmdplant
_pair = _r1278._pair
_base_build = _r1278.build_episode
FACTORY = _r1278.FACTORY
GEN = _r1278.GEN
FACTORY_DIR = _r1278.FACTORY_DIR
PR0 = _r1278.PR0
ISSUE0 = _r1278.ISSUE0
_trim = _r1278._trim

BAN = set(_r1278.BAN) | {
    "advice-diverging-false",
    "http-ssltry-false",
    "merge-conflictstyle-diff3",
    "interactive-difffilter-legacy",
    "whoosh-writer-leftover3d-rebuild",
    "whoosh-drop-leftover3d-handoff",
}


def _prior_mill_slugs() -> set[str]:
    used: set[str] = set()
    for path in HERE.glob("gor-mill-*.py"):
        if path.name == Path(__file__).name:
            continue
        used.update(re.findall(r'slug="([^"]+)"', path.read_text()))
    return used


PRIOR = _prior_mill_slugs()


def _published_slugs() -> set[str]:
    used: set[str] = set(PRIOR)
    if not FACTORY_DIR.exists():
        return used
    for path in FACTORY_DIR.glob("batch-r*.jsonl"):
        stem = path.stem
        try:
            n = int(stem.split("r", 1)[1])
        except ValueError:
            continue
        if n < 1278:
            continue
        for line in path.read_text().splitlines():
            if not line.strip():
                continue
            rec = json.loads(line)
            match = re.match(r"gor-r\d+-(.+)$", rec.get("id", ""))
            if match:
                used.add(match.group(1))
    return used


def densify(ep: dict, spec: dict) -> dict:
    steps = ep["steps"]
    stop = steps.pop()
    src = spec["src"]
    stem = Path(src).stem
    persist_cmd = (
        f"git config --local --show-origin --list | rg -n {stem} | tail; "
        f"git diff --stat HEAD~1 -- {src}; git status -sb"
    )
    persist_obs = f"{spec['left_obs']}\n {src} leftover | 4 +-\n## leftover recover/{stem}"
    fsck_cmd = "git fsck --no-dangling --connectivity-only 2>&1 | tail; git reflog -3 --date=iso | tail"
    fsck_obs = f"(empty leftover fsck)\nHEAD@{{0}}: leftover recover/{stem}"
    if steps:
        obs0 = str(steps[0].get("observation", ""))
        if "git" not in obs0.casefold() and "rebase" not in obs0.casefold() and "ci" not in obs0.casefold():
            steps[0]["observation"] = (obs0 + "\ngit rebase leftover; detached HEAD; CI").strip()
        if len(steps) > 1:
            obs1 = str(steps[1].get("observation", ""))
            if (
                "failure" not in obs1.casefold()
                and "broken" not in obs1.casefold()
                and "conflict" not in obs1.casefold()
                and "detached" not in obs1.casefold()
            ):
                steps[1]["observation"] = (
                    obs1 + "\nbroken leftover rebase conflict; detached HEAD; CI failure"
                ).strip()
    steps.append(
        {
            "n": 14,
            "decision_basis": _trim(
                f"Observation: persist leftover recover for {stem}; show origin and diffstat."
            ),
            "tool_call": {"name": "bash", "args": {"command": persist_cmd}},
            "observation": persist_obs,
        }
    )
    steps.append(
        {
            "n": 15,
            "decision_basis": "Observation: fsck after recover; reflog records the hotfix commit.",
            "tool_call": {"name": "bash", "args": {"command": fsck_cmd}},
            "observation": fsck_obs,
        }
    )
    stop["n"] = 16
    stop["decision_basis"] = "Observation: stop."
    steps.append(stop)
    for i, st in enumerate(steps, 1):
        st["n"] = i
        if len(st["decision_basis"]) > 240:
            raise SystemExit(f"{ep['id']} step {i} basis")
    ep["reward"]["cost_steps"] = 16
    if not (12 <= len(steps) <= 18):
        raise SystemExit(f"{ep['id']} {len(steps)} steps")
    return ep


def build_episode(round_n: int, spec: dict, *, success: bool, pr: int, issue: int | None, inc: str) -> dict:
    ep = _base_build(round_n, spec, success=success, pr=pr, issue=issue, inc=inc)
    return densify(ep, spec)


NEW_PAIRS: list[tuple[dict, dict]] = []


def add(a: dict, b: dict) -> None:
    NEW_PAIRS.append(_pair(a, b))


def _cfg(slug: str, stem: str, key: str, bad: str, good: str | None, effect: str, probe: str,
         bad_obs: str, good_obs: str, wrong: str, wrong_obs: str, *, handoff: bool = False,
         old: str = "0", new: str = "7", kind: str = "config") -> dict:
    kw: dict = dict(
        slug=slug,
        repo=f"{slug.split('-')[0]}-ops/{stem}",
        marker=stem.upper() + "_N",
        old=old,
        new=new,
        stem=stem,
        key=key,
        bad=bad,
        good=good,
        effect=effect,
        probe=probe,
        bad_obs=bad_obs,
        good_obs=good_obs,
        wrong=wrong,
        wrong_obs=wrong_obs,
        kind=kind,
    )
    if handoff:
        kw["handoff"] = f"ci-{slug}"
        kw["ci_obs"] = bad
    return gitcfg(**kw)


def _cmd(slug: str, stem: str, knob: str, effect: str, map_cmd: str, map_obs: str,
         wrong: str, wrong_obs: str, rec_cmd: str, rec_obs: str, left_cmd: str, left_obs: str,
         *, handoff: bool = False, old: str = "1", new: str = "6") -> dict:
    kw: dict = dict(
        slug=slug,
        repo=f"{slug.split('-')[1] if slug.startswith('git-') else slug.split('-')[0]}-ops/{stem}",
        marker=stem.upper() + "_N",
        old=old,
        new=new,
        stem=stem,
        knob=knob,
        effect=effect,
        map_cmd=map_cmd,
        map_obs=map_obs,
        wrong=wrong,
        wrong_obs=wrong_obs,
        rec_cmd=rec_cmd,
        rec_obs=rec_obs,
        left_cmd=left_cmd,
        left_obs=left_obs,
    )
    if handoff:
        kw["handoff"] = f"ci-{slug}"
        kw["ci_obs"] = map_obs.split("\n")[0]
        kw["ci_probe"] = f"ssh ci-runner '{map_cmd.split(';')[0]}'"
    return cmdplant(**kw)


